<?php
declare(strict_types=1); namespace OCA\ERP\Controller;
use OCA\ERP\Permissions\PermissionLevel; use OCA\ERP\Permissions\ResourceType; use OCA\ERP\Service\MeasurementRecordService; use OCA\ERP\Service\MeasurementBlockService; use OCA\ERP\Service\MeasurementAssetService; use OCA\ERP\Service\ProjectService; use OCA\ERP\Service\PermissionService; use OCP\AppFramework\Http\Attribute\NoAdminRequired; use OCP\AppFramework\Http\DataResponse; use OCP\AppFramework\OCS\OCSBadRequestException; use OCP\AppFramework\OCS\OCSNotFoundException; use OCP\AppFramework\OCS\OCSPreconditionFailedException; use OCP\IRequest; use OCP\IUserSession;
class MeasurementRecordController extends AbstractResourceController { public function __construct(string $appName,IRequest $request,private MeasurementRecordService $records,private MeasurementBlockService $blocks,private MeasurementAssetService $assets,private ProjectService $projects,PermissionService $permissions,IUserSession $session){parent::__construct($appName,$request,$permissions,$session);} protected function resource():ResourceType{return ResourceType::Projekte;} #[NoAdminRequired] public function index(int $projectId):DataResponse{$this->requireLevel(PermissionLevel::Read);return new DataResponse($this->records->listByProject($projectId));} #[NoAdminRequired] public function show(int $id):DataResponse{$this->requireLevel(PermissionLevel::Read);try{return new DataResponse(['record'=>$this->records->get($id),'blocks'=>$this->blocks->list($id)]);}catch(\OutOfBoundsException){throw new OCSNotFoundException('Measurement record not found');}} #[NoAdminRequired] public function create(int $projectId,string $title):DataResponse{$u=$this->requireLevel(PermissionLevel::Write);try{$this->projects->getProject($projectId);return new DataResponse($this->records->createDraft($projectId,$u->getUID(),$title));}catch(\InvalidArgumentException $e){throw new OCSBadRequestException($e->getMessage());}catch(\OutOfBoundsException){throw new OCSNotFoundException('Project not found');}} #[NoAdminRequired] public function transition(int $id,string $status):DataResponse{$u=$this->requireLevel(PermissionLevel::Write);try{return new DataResponse($this->records->transitionStatus($id,$status,$u->getUID()));}catch(\OutOfBoundsException){throw new OCSNotFoundException('Measurement record not found');}catch(\DomainException $e){throw new OCSPreconditionFailedException($e->getMessage());}} #[NoAdminRequired] public function addBlock(int $id,string $type,array $payload):DataResponse{return $this->block(fn()=>$this->blocks->create($id,$type,$payload));} #[NoAdminRequired] public function updateBlock(int $recordId,int $id,array $payload):DataResponse{return $this->block(fn()=>$this->blocks->update($recordId,$id,$payload));} #[NoAdminRequired] public function deleteBlock(int $recordId,int $id):DataResponse{return $this->block(fn()=>$this->blocks->delete($recordId,$id));} #[NoAdminRequired] public function reorderBlocks(int $id,array $blockIds):DataResponse{return $this->block(fn()=>$this->blocks->reorder($id,$blockIds));} #[NoAdminRequired] public function uploadAsset(int $projectId,string $content):DataResponse{$user=$this->requireLevel(PermissionLevel::Write);try{return new DataResponse($this->assets->store($this->projects->getProject($projectId),$user,$content));}catch(\InvalidArgumentException $e){throw new OCSBadRequestException($e->getMessage());}catch(\OutOfBoundsException){throw new OCSNotFoundException('Project not found');}} private function block(callable $operation):DataResponse{$this->requireLevel(PermissionLevel::Write);try{return new DataResponse($operation());}catch(\InvalidArgumentException $e){throw new OCSBadRequestException($e->getMessage());}catch(\OutOfBoundsException){throw new OCSNotFoundException('Measurement block not found');}} }
